/* Songbook service worker — app-shell cache + stale-while-revalidate.
 *
 * ENV, VERSION and CORE are generated by build_pages.py from the actual
 * _site/ contents, so the precache manifest and cache-busting version can
 * never drift from what is deployed. Do not edit the blocks below by hand;
 * edit the build script instead. The inline values here are a safe fallback
 * for running the source tree (unbuilt) directly.
 *
 * GitHub Pages serves prod (/songbook/) and dev (/songbook/dev/) from one
 * origin. CacheStorage is origin-scoped, not path-scoped, so both workers
 * see each other's caches: every cache name is namespaced by ENV and
 * activate only prunes its own namespace. Without that, whichever worker
 * activated last would delete the other environment's offline cache.
 */
'use strict';

/* @generated-version:start */
var VERSION = 'dev';
/* @generated-version:end */

/* Environment is derived from where this file is served, not baked in at
 * build time, so the dev and prod artifacts stay byte-identical: what gets
 * smoke-tested on /songbook/dev/ is exactly what ships to /songbook/.
 *
 * The same rule is duplicated in js/core.js (SB.envFor) for the page side —
 * keep the two in step; tests/env.py asserts they agree.
 */
function envFor(pathname) {
    var parts = String(pathname).split('/');
    // drop a trailing filename ('index.html', 'sw.js') or the empty segment
    // left by a trailing slash, so the last entry is the containing directory
    return parts[parts.length - 2] === 'dev' ? 'dev' : 'prod';
}

var ENV = envFor(self.location.pathname);
var PREFIX = 'songbook-' + ENV + '-';
var SHELL = PREFIX + 'shell-' + VERSION;
var RUNTIME = PREFIX + 'runtime-' + VERSION;

/* @generated-core:start */
var CORE = [
    './',
    'index.html',
    'chords.js',
    'tuner.js',
    'style.css',
    'manifest.webmanifest',
    'songbooks/index.json'
];
/* @generated-core:end */

self.addEventListener('install', function (e) {
    e.waitUntil(
        caches.open(SHELL).then(function (c) {
            // cache.addAll() is atomic: one 404 rejects the whole batch and
            // leaves the shell empty. Precache per asset instead so a single
            // missing file really is tolerated, as intended.
            return Promise.all(CORE.map(function (path) {
                return c.add(path).catch(function () { /* skip this asset */ });
            }));
        }).then(function () { return self.skipWaiting(); })
    );
});

self.addEventListener('activate', function (e) {
    e.waitUntil(
        caches.keys().then(function (keys) {
            return Promise.all(keys.map(function (k) {
                // Only prune this environment's old versions; caches belonging
                // to the other environment (or anything else on the origin)
                // are left alone.
                if (k.indexOf(PREFIX) !== 0) return;
                if (k !== SHELL && k !== RUNTIME) return caches.delete(k);
            }));
        }).then(function () { return self.clients.claim(); })
    );
});

function isSameOriginGet(req) {
    if (req.method !== 'GET') return false;
    var url = new URL(req.url);
    return url.origin === self.location.origin;
}

self.addEventListener('fetch', function (e) {
    var req = e.request;
    if (!isSameOriginGet(req)) return;

    // Navigations: network-first so deploys are picked up, cache fallback offline.
    if (req.mode === 'navigate') {
        e.respondWith(
            fetch(req).then(function (res) {
                var copy = res.clone();
                caches.open(SHELL).then(function (c) { c.put('index.html', copy); });
                return res;
            }).catch(function () {
                return caches.match('index.html').then(function (r) { return r || caches.match('./'); });
            })
        );
        return;
    }

    // Everything else same-origin: stale-while-revalidate.
    e.respondWith(
        caches.match(req).then(function (cached) {
            var network = fetch(req).then(function (res) {
                if (res && res.ok) {
                    var copy = res.clone();
                    caches.open(RUNTIME).then(function (c) { c.put(req, copy); });
                }
                return res;
            }).catch(function () { return cached; });
            return cached || network;
        })
    );
});
